def get_remote_firefox():
    options = Options()
    options.add_argument("--headless")  # opcional, recomendable para CI

    return webdriver.Remote(
        command_executor="http://selenium-hub:4444/wd/hub",
        options=options,
        desired_capabilities=DesiredCapabilities.FIREFOX
    )

class TestFtestaccesoLibreNormal():
  def setup_method(self, method):
    self.driver = get_remote_firefox()
    self.vars = {}
  
  def teardown_method(self, method):
    self.driver.quit()
  
  def test_ftestaccesoLibreNormal(self):
    print("`set speed` is a no-op in code export, use `pause` instead")
    self.driver.get("http://cael-test:8000/acceso/registro/libre")
    self.driver.set_window_size(1112, 867)
    self.driver.find_element(By.ID, "codigoAlumno").click()
    time.sleep(1)
    self.driver.find_element(By.ID, "codigoAlumno").send_keys("2010766")
    time.sleep(1)
    self.driver.find_element(By.ID, "maquina").click()
    time.sleep(1)
    dropdown = self.driver.find_element(By.ID, "maquina")
    time.sleep(1)
    dropdown.find_element(By.XPATH, "//option[. = 'LAB-01']").click()
    time.sleep(1)
    self.driver.find_element(By.CSS_SELECTOR, "#maquina > option:nth-child(2)").click()
    time.sleep(1)
    self.driver.find_element(By.ID, "motivo").click()
    time.sleep(1)
    dropdown = self.driver.find_element(By.ID, "motivo")
    time.sleep(1)
    dropdown.find_element(By.XPATH, "//option[. = 'Revisar correo']").click()
    time.sleep(1)
    self.driver.find_element(By.CSS_SELECTOR, "#motivo > option:nth-child(2)").click()
    time.sleep(1)
    self.driver.find_element(By.CSS_SELECTOR, ".btn-primary").click()
    time.sleep(1)
    assert self.driver.find_element(By.ID, "mensajeLibre").text == "Entrada libre registrada correctamente."
  
